from dynamodb.entity.todo.todo_entity import TodoEntity
from dynamodb.entity.todo.todo_entity_repo import TodoEntityRepo, TodoQueryResponse
from dynamodb.entity.todo.todo_entity_service import TodoEntityService


class TodoService:

    def __init__(self):
        self.entity_service = TodoEntityService(TodoEntityRepo())

    def find_all_todo_by_list_id(self, list_id: str) -> TodoQueryResponse:
        return self.entity_service.find_all_todo_by_list_id(list_id=list_id)

    def put_todo(self, todo: TodoEntity) -> TodoEntity:
        return self.entity_service.put_todo(todo)

    def update_todo(self, list_id: str, todo_id: str, updates: dict):
        return self.entity_service.update_todo(list_id=list_id, todo_id=todo_id, updates=updates)
